div.script:
(function() {
    var form = document.getElementById('portal_leave_form');
    var select = document.getElementById('leave_type_select');
    var dateToSection = document.getElementById('leave_section_date_to');
    var halfSection = document.getElementById('leave_section_half_day');
    var hourSection = document.getElementById('leave_section_hour');
    var hourMultiSection = document.getElementById('leave_section_hour_multi');
    var multiDayCheck = document.getElementById('leave_multi_day');
    var dateFrom = document.getElementById('request_date_from');
    var dateTo = document.getElementById('request_date_to');
    var hourFrom = document.querySelector('#leave_section_hour select[name="request_hour_from"]');
    var hourTo = document.querySelector('#leave_section_hour select[name="request_hour_to"]');
    var restrictionsAlert = document.getElementById('portal_leave_restrictions_alert');
    var restrictionTimer = null;

    function collectLeaveParams() {
        var typeId = select.value;
        var fromVal = dateFrom.value;
        var toVal = dateTo.value;
        if (!typeId || !fromVal) {
            return null;
        }
        if (document.getElementById('leave_section_hour').style.display !== 'none' && !multiDayCheck.checked) {
            toVal = fromVal;
        }
        var params = {
            holiday_status_id: parseInt(typeId, 10),
            request_date_from: fromVal,
            request_date_to: toVal || fromVal
        };
        var unit = select.options[select.selectedIndex].getAttribute('data-request-unit');
        if (unit === 'half_day') {
            params.request_date_from_period = document.querySelector('#portal_leave_form select[name="request_date_from_period"]').value;
            params.request_date_to_period = document.querySelector('#portal_leave_form select[name="request_date_to_period"]').value;
        } else if (unit === 'hour' && hourFrom && hourTo) {
            params.request_hour_from = hourFrom.value ? hourFrom.value + ':00' : '';
            params.request_hour_to = hourTo.value ? hourTo.value + ':00' : '';
        }
        return params;
    }

    function renderRestrictionsAlert(blocking, warnings, errorStr) {
        if (!restrictionsAlert) return;
        restrictionsAlert.className = 'alert mb-3';
        restrictionsAlert.innerHTML = '';
        restrictionsAlert.classList.add('d-none');
        if (errorStr) {
            restrictionsAlert.classList.remove('d-none');
            restrictionsAlert.classList.add('alert-danger');
            restrictionsAlert.textContent = errorStr;
            return;
        }
        var msgs = [];
        if (blocking && blocking.length) {
            restrictionsAlert.classList.remove('d-none');
            restrictionsAlert.classList.add('alert-danger');
            msgs = msgs.concat(blocking);
        } else if (warnings && warnings.length) {
            restrictionsAlert.classList.remove('d-none');
            restrictionsAlert.classList.add('alert-warning');
            msgs = msgs.concat(warnings);
        }
        if (!msgs.length) return;
        var ul = document.createElement('ul');
        ul.className = 'mb-0 ps-3';
        msgs.forEach(function(t) {
            var li = document.createElement('li');
            li.textContent = t;
            ul.appendChild(li);
        });
        restrictionsAlert.appendChild(ul);
    }

    function runRestrictionsCheck() {
        var params = collectLeaveParams();
        if (!params) {
            renderRestrictionsAlert([], [], null);
            return;
        }
        var csrf = document.querySelector('#portal_leave_form input[name="csrf_token"]');
        var headers = {'Content-Type': 'application/json'};
        if (csrf) headers['X-CSRF-TOKEN'] = csrf.value;
        fetch('/my/leaves/check_restrictions', {
            method: 'POST',
            headers: headers,
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params,
                id: 1
            })
        }).then(function(r) { return r.json(); }).then(function(resp) {
            var data = resp.result || resp;
            if (!data) {
                renderRestrictionsAlert([], [], 'No se pudo validar la solicitud.');
                return;
            }
            if (data.error) {
                renderRestrictionsAlert([], [], String(data.error));
                return;
            }
            renderRestrictionsAlert(data.blocking || [], data.warnings || [], null);
        }).catch(function() {
            renderRestrictionsAlert([], [], 'Error de red al validar.');
        });
    }

    function scheduleRestrictionsCheck() {
        if (restrictionTimer) clearTimeout(restrictionTimer);
        restrictionTimer = setTimeout(runRestrictionsCheck, 450);
    }

    function updateSections() {
        var opt = select.options[select.selectedIndex];
        var unit = opt ? (opt.getAttribute('data-request-unit') || 'day') : 'day';
        var isHour = (unit === 'hour');
        var isHalfDay = (unit === 'half_day');

        halfSection.style.display = isHalfDay ? 'block' : 'none';
        hourSection.style.display = isHour ? 'block' : 'none';
        hourMultiSection.style.display = isHour ? 'block' : 'none';

        if (isHour) {
            dateToSection.style.display = multiDayCheck.checked ? 'block' : 'none';
            dateTo.required = multiDayCheck.checked;
            if (!multiDayCheck.checked) dateTo.value = dateFrom.value;
        } else {
            dateToSection.style.display = 'block';
            dateTo.required = false;
        }
        if (hourFrom) hourFrom.required = isHour;
        if (hourTo) hourTo.required = isHour;
        scheduleRestrictionsCheck();
    }

    function onMultiDayChange() {
        dateToSection.style.display = multiDayCheck.checked ? 'block' : 'none';
        dateTo.required = multiDayCheck.checked;
        if (!multiDayCheck.checked) {
            dateTo.value = dateFrom.value;
        }
        scheduleRestrictionsCheck();
    }

    form.addEventListener('submit', function() {
        if (document.getElementById('leave_section_hour').style.display !== 'none' && !multiDayCheck.checked) {
            dateTo.value = dateFrom.value;
        }
        if (!dateTo.value && dateFrom.value) {
            dateTo.value = dateFrom.value;
        }
    });

    select.addEventListener('change', updateSections);
    if (multiDayCheck) multiDayCheck.addEventListener('change', onMultiDayChange);
    if (dateFrom) dateFrom.addEventListener('change', function() {
        if (document.getElementById('leave_section_hour').style.display !== 'none' && !multiDayCheck.checked) {
            dateTo.value = dateFrom.value;
        }
        scheduleRestrictionsCheck();
    });
    if (dateTo) dateTo.addEventListener('change', scheduleRestrictionsCheck);
    var halfSel = document.querySelectorAll('#leave_section_half_day select');
    if (halfSel.length) {
        halfSel.forEach(function(el) { el.addEventListener('change', scheduleRestrictionsCheck); });
    }
    if (hourFrom) hourFrom.addEventListener('change', scheduleRestrictionsCheck);
    if (hourTo) hourTo.addEventListener('change', scheduleRestrictionsCheck);

    if (select.value) updateSections();

    var btnSimulate = document.getElementById('btn_simulate');
    var resultSpan = document.getElementById('simulate_result');
    if (btnSimulate && resultSpan) {
        btnSimulate.addEventListener('click', function() {
            var params = collectLeaveParams();
            if (!params) {
                resultSpan.textContent = 'Seleccione tipo y fecha desde.';
                return;
            }
            resultSpan.textContent = 'Calculando...';
            var csrf = document.querySelector('input[name="csrf_token"]');
            var headers = {'Content-Type': 'application/json'};
            if (csrf) headers['X-CSRF-TOKEN'] = csrf.value;
            var body = JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params,
                id: 1
            });
            fetch('/my/leaves/simulate', {
                method: 'POST',
                headers: headers,
                body: body
            }).then(function(r) { return r.json(); }).then(function(resp) {
                var data = resp.result || resp;
                if (data && data.error) {
                    resultSpan.textContent = 'Error: ' + data.error;
                } else if (data) {
                    var txt = 'Días: ' + data.number_of_days + ' | Saldo disponible: ' + data.virtual_remaining_leaves;
                    if (data.number_of_hours > 0) txt += ' | Horas: ' + data.number_of_hours;
                    resultSpan.textContent = txt;
                } else {
                    resultSpan.textContent = 'Error al simular.';
                }
            }).catch(function() {
                resultSpan.textContent = 'Error al simular.';
            });
        });
    }
})();

t.script:
(function() {
    var calendarEl = document.getElementById('portal_calendar');
    if (!calendarEl) return;
    var csrf = document.querySelector('input[name="csrf_token"]');
    var headers = {'Content-Type': 'application/json'};
    if (csrf) headers['X-CSRF-TOKEN'] = csrf.value;
    var calendar = new FullCalendar.Calendar(calendarEl, {
        initialView: 'dayGridMonth',
        locale: 'es',
        headerToolbar: { left: 'prev,next today', center: 'title', right: 'dayGridMonth,listWeek' },
        events: function(info, successCallback, failureCallback) {
            var body = JSON.stringify({ jsonrpc: '2.0', method: 'call', params: { start: info.startStr, end: info.endStr }, id: 1 });
            fetch('/my/calendar/events', { method: 'POST', headers: headers, body: body })
                .then(function(r) { return r.json(); })
                .then(function(resp) { successCallback((resp.result || resp) || []); })
                .catch(function() { failureCallback(); });
        },
        eventClick: function(info) { if (info.event.url) window.location = info.event.url; }
    });
    calendar.render();
})();

